import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/ROC.md","filePath":"manual-en/ROC.md","lastUpdated":1785684581000}'),i={name:"manual-en/ROC.md"};function s(r,e,n,c,h,l){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h3 id="_15-19-roc" tabindex="-1">15.19 ROC <a class="header-anchor" href="#_15-19-roc" aria-label="Permalink to &quot;15.19 ROC&quot;">​</a></h3><pre><code>ROC     var_list BY state_var (state_value)
        /PLOT = { CURVE [(REFERENCE)], NONE }
        /PRINT = [ SE ] [ COORDINATES ]
        /CRITERIA = [ CUTOFF({INCLUDE,EXCLUDE}) ]
          [ TESTPOS ({LARGE,SMALL}) ]
          [ CI (confidence) ]
          [ DISTRIBUTION ({FREE, NEGEXPO }) ]
        /MISSING={EXCLUDE,INCLUDE}
</code></pre><p>The <code>ROC</code> command is used to plot the receiver operating characteristic curve of a dataset, and to estimate the area under the curve. This is useful for analysing the efficacy of a variable as a predictor of a state of nature.</p><p>The mandatory var_list is the list of predictor variables. The variable state_var is the variable whose values represent the actual states, and state_value is the value of this variable which represents the positive state.</p><p>The optional subcommand <code>PLOT</code> is used to determine if and how the <code>ROC</code> curve is drawn. The keyword <code>CURVE</code> means that the <code>ROC</code> curve should be drawn, and the optional keyword <code>REFERENCE</code>, which should be enclosed in parentheses, says that the diagonal reference line should be drawn. If the keyword <code>NONE</code> is given, then no <code>ROC</code> curve is drawn. By default, the curve is drawn with no reference line.</p><p>The optional subcommand <code>PRINT</code> determines which additional tables should be printed. Two additional tables are available. The <code>SE</code> keyword says that standard error of the area under the curve should be printed as well as the area itself. In addition, a p-value for the null hypothesis that the area under the curve equals 0.5 is printed. The <code>COORDINATES</code> keyword says that a table of coordinates of the <code>ROC</code> curve should be printed.</p><p>The <code>CRITERIA</code> subcommand has four optional parameters:</p><ul><li>The <code>TESTPOS</code> parameter may be <code>LARGE</code> or <code>SMALL</code>. <code>LARGE</code> is the default, and says that larger values in the predictor variables are to be considered positive. <code>SMALL</code> indicates that smaller values should be considered positive.</li><li>The <code>CI</code> parameter specifies the confidence interval that should be printed. It has no effect if the <code>SE</code> keyword in the <code>PRINT</code> subcommand has not been given.</li><li>The <code>DISTRIBUTION</code> parameter determines the method to be used when estimating the area under the curve. There are two possibilities, <em>viz</em> : <code>FREE</code> and <code>NEGEXPO</code>. The <code>FREE</code> method uses a non-parametric estimate, and the <code>NEGEXPO</code> method a bi-negative exponential distribution estimate. The <code>NEGEXPO</code> method should only be used when the number of positive actual states is equal to the number of negative actual states. The default is <code>FREE</code>.</li><li>The <code>CUTOFF</code> parameter is for compatibility and is ignored.</li></ul><p>The <code>MISSING</code> subcommand determines whether user missing values are to be included or excluded in the analysis. The default behaviour is to exclude them. Cases are excluded on a listwise basis; if any of the variables in var_list or if the variable state_var is missing, then the entire case is excluded.</p>`,9)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
